import{g as t,o as a,c as o,al as i}from"./chunks/framework.DmZZ3Cb1.js";const h=JSON.parse('{"title":"03 标签与图标","description":"标签从哪来、首页标签云的 56 个词、图标来源与新增标签的完整步骤。","frontmatter":{"title":"03 标签与图标","description":"标签从哪来、首页标签云的 56 个词、图标来源与新增标签的完整步骤。"},"headers":[],"relativePath":"notes/writing-guide/03-tags.md","filePath":"notes/writing-guide/03-tags.md","lastUpdated":1793364501000}'),r={name:"notes/writing-guide/03-tags.md"};function s(n,e,c,d,l,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="标签与图标" tabindex="-1">标签与图标 <a class="header-anchor" href="#标签与图标" aria-label="Permalink to &quot;标签与图标&quot;">​</a></h1><p>标签只来自文章的 frontmatter。标签页在构建时读取所有文章自动聚合，不需要另外维护列表。</p><h2 id="正在使用的标签" tabindex="-1">正在使用的标签 <a class="header-anchor" href="#正在使用的标签" aria-label="Permalink to &quot;正在使用的标签&quot;">​</a></h2><p>点标签名可以直接打开对应的聚合页：</p><table tabindex="0"><thead><tr><th>标签</th><th>聚合页</th></tr></thead><tbody><tr><td><code>Markdown</code></td><td><a href="/pages/tags?q=Markdown">查看 Markdown 标签页</a></td></tr><tr><td><code>AI</code></td><td><a href="/pages/tags?q=AI">查看 AI 标签页</a></td></tr><tr><td><code>Tencent</code></td><td><a href="/pages/tags?q=Tencent">查看 Tencent 标签页</a></td></tr><tr><td><code>Skill</code></td><td><a href="/pages/tags?q=Skill">查看 Skill 标签页</a></td></tr><tr><td><code>图片</code></td><td><a href="/pages/tags?q=图片">查看 图片 标签页</a></td></tr></tbody></table><p>标签页按文章数量排序，数量相同按字母序。新增标签不需要注册，在 frontmatter 的 <code>tags</code> 里写上就会自动出现；没有专属图标的标签会退回默认图标。</p><h2 id="首页标签云" tabindex="-1">首页标签云 <a class="header-anchor" href="#首页标签云" aria-label="Permalink to &quot;首页标签云&quot;">​</a></h2><p>首页那排滚动的标签是展示用的完整词表，目前共 56 个，比实际文章用到的多。其中一部分还没有文章，点进去是空列表。</p><ul><li><strong>语言、框架与开发</strong>：JavaScript、TypeScript、Vue.js、React、Next.js、Python、CSS、Sass、TailwindCSS、SVG、SSR、状态管理、Router、Element、webpack、npm、Node.js、前端、后端、数据库、Vite</li><li><strong>平台、网络与工具</strong>：Vercel、CloudFlare、nginx、Docker、Linux、Git、Github、Hexo、Windows、MacOS、VSCode、终端、浏览器、HTTP、OPPO、APP</li><li><strong>AI、内容与设计</strong>：AI、Tencent、Markdown、Skill、Obsidian、Design、PS、图标、图片、字体、图表、术语、网站</li><li><strong>生活与记录</strong>：摄影、旅行、视频、效率、工具、博客</li></ul><div class="rp-callout rp-callout--warning"><div class="rp-callout__title">别为了凑标签而写标签</div><div class="rp-callout__content"><p>标签页只展示有文章的分类。想启用一个新标签，先写一篇带该标签的文章，它才会出现在标签页里。</p></div></div><h2 id="图标从哪里来" tabindex="-1">图标从哪里来 <a class="header-anchor" href="#图标从哪里来" aria-label="Permalink to &quot;图标从哪里来&quot;">​</a></h2><p>所有标签图标都来自 <a href="https://icon-sets.iconify.design/" target="_blank" rel="noreferrer">Iconify</a>，最初是从 note.weizwz.com 把内联 SVG 提取下来，存放在 <code>docs/.vitepress/theme/components/icons/tagIcons.ts</code>。</p><p>常用入口：</p><ul><li>图标库搜索：<a href="https://icon-sets.iconify.design/" target="_blank" rel="noreferrer">icon-sets.iconify.design</a></li><li>MDI（Material Design Icons）：<a href="https://icon-sets.iconify.design/mdi/" target="_blank" rel="noreferrer">icon-sets.iconify.design/mdi</a></li><li>Simple Icons（品牌图标）：<a href="https://icon-sets.iconify.design/simple-icons/" target="_blank" rel="noreferrer">icon-sets.iconify.design/simple-icons</a></li><li>Material Symbols：<a href="https://icon-sets.iconify.design/material-symbols/" target="_blank" rel="noreferrer">icon-sets.iconify.design/material-symbols</a></li><li>Lucide：<a href="https://icon-sets.iconify.design/lucide/" target="_blank" rel="noreferrer">icon-sets.iconify.design/lucide</a></li><li>Tabler：<a href="https://icon-sets.iconify.design/tabler/" target="_blank" rel="noreferrer">icon-sets.iconify.design/tabler</a></li></ul><p>直接取 SVG：单个图标打开 <code>https://api.iconify.design/mdi/camera.svg</code>，批量取可以看 <code>https://api.iconify.design/mdi.json?icons=camera,server,database</code>。</p><h2 id="新增一个标签的步骤" tabindex="-1">新增一个标签的步骤 <a class="header-anchor" href="#新增一个标签的步骤" aria-label="Permalink to &quot;新增一个标签的步骤&quot;">​</a></h2><ol><li>在 Iconify 搜到图标，记下 <code>前缀:名称</code>，例如 <code>mdi:camera</code>。</li><li>打开 <code>https://api.iconify.design/mdi/camera.svg</code>，复制里面的 <code>&lt;path&gt;</code>。</li><li>在 <code>tagIcons.ts</code> 新增 <code>export const TagXxxIcon = ...</code>，class 保持 <code>mr-1 h-4 w-4 text-[rgb(...)]</code>，颜色按品牌色调整。</li><li>在同文件的 <code>tagIcons</code> 映射末尾加一行 <code>&quot;标签名&quot;: TagXxxIcon</code>。</li><li>在 <code>HeroCard.vue</code> 的 <code>tags</code> 数组里加 <code>{ label: &quot;标签名&quot;, href: &quot;pages/tags?q=...&quot; }</code>；中文标签的 <code>href</code> 要用 <code>encodeURIComponent</code> 编码。</li><li>没配图标的标签不会报错，标签页会退回 <code>TagDefaultIcon</code>。</li></ol><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">只想让文章有图标，不动首页</div><div class="rp-callout__content"><p>第 1–4 步就够了：文章卡片和标签页都走 <code>tagIcons</code> 查表。第 5 步只影响首页那排标签云。</p></div></div>',18)])])}const f=t(r,[["render",s]]);export{h as __pageData,f as default};
